import{_ as a,o,c as r,a0 as e}from"./chunks/framework.Caz7a20Z.js";const h=JSON.parse('{"title":"摸了一天？但服务器上线了嘿嘿","description":"今天好像什么也没怎么做，就又把几个论文的思路开展了一下，然后买了阿里云服务器、把渔业信息聚合系统部署上去了，就这样吧，明天好好学习。","frontmatter":{"title":"摸了一天？但服务器上线了嘿嘿","date":"2026-09-20T00:00:00.000Z","tags":["日记"],"description":"今天好像什么也没怎么做，就又把几个论文的思路开展了一下，然后买了阿里云服务器、把渔业信息聚合系统部署上去了，就这样吧，明天好好学习。"},"headers":[],"relativePath":"posts/diary-20260920.md","filePath":"posts/diary-20260920.md","lastUpdated":null}'),s={name:"posts/diary-20260920.md"};function n(p,t,i,d,l,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="摸了一天-但服务器上线了嘿嘿" tabindex="-1">摸了一天？但服务器上线了嘿嘿 <a class="header-anchor" href="#摸了一天-但服务器上线了嘿嘿" aria-label="Permalink to &quot;摸了一天？但服务器上线了嘿嘿&quot;">​</a></h1><p>今天回头一看，好像也没干成什么&quot;大事&quot;，但细数下来也不是全白过——<strong>又有几个论文的思路开展了一下</strong>，还<strong>买了阿里云服务器、把渔业信息聚合系统部署上线了</strong> 🖥️🚀。</p><h2 id="论文-几个新思路冒出来了" tabindex="-1">论文：几个新思路冒出来了 <a class="header-anchor" href="#论文-几个新思路冒出来了" aria-label="Permalink to &quot;论文：几个新思路冒出来了&quot;">​</a></h2><p>今天没怎么写正文，主要是在<strong>想</strong>——又有几个论文的思路开展了一下 💡。</p><p>这种日子看起来&quot;没产出&quot;，其实挺重要的。前面那段一直在埋头改稿、赶汇报，脑子基本被别人的意见牵着走；今天算是把它收回来自己转了转，几个新点子在脑子里冒头，先记下来、先铺开，等哪天回过头来看，说不定就从&quot;一个念头&quot;长成&quot;一篇稿子&quot;了。</p><p>想清楚要做什么，有时候比埋头做更重要嘛。</p><h2 id="阿里云服务器-渔业信息聚合系统上线了" tabindex="-1">阿里云服务器：渔业信息聚合系统上线了！ <a class="header-anchor" href="#阿里云服务器-渔业信息聚合系统上线了" aria-label="Permalink to &quot;阿里云服务器：渔业信息聚合系统上线了！&quot;">​</a></h2><p>今天最实的一件事——<strong>买了阿里云的服务器，然后把之前搞的渔业信息聚合系统部署上去了</strong> ☁️🐟。</p><p>从&quot;本地能跑&quot;到&quot;挂在网上有个能访问的域名&quot;，这一步跨过去的感觉还挺不一样的。之前它只是我电脑上的一个项目，现在它是个<strong>真的在线的服务</strong>了——哪怕目前只有我自己会用，那个&quot;随时能打开&quot;的感觉还是挺让人满足的嘿嘿。</p><p>买服务器这事本身也有点仪式感：算是第一次正儿八经为自己的项目掏钱租地方住。希望它别太费钱🙏。</p><h2 id="就这样-明天好好学习" tabindex="-1">就这样，明天好好学习 <a class="header-anchor" href="#就这样-明天好好学习" aria-label="Permalink to &quot;就这样，明天好好学习&quot;">​</a></h2><p>今天总结：论文思路又铺开了几个 🌱，渔业信息聚合系统正式上云 ✅，中间可能摸了不少鱼 🐟（划掉）。</p><p><strong>就这样吧，明天好好学习</strong> 📚。</p><p>偶尔有这么一天松一松也没什么不好，充完电明天接着干活。加油 💪！</p>',14)])])}const q=a(s,[["render",n]]);export{h as __pageData,q as default};
